def _hazard_noun(h_plain: str) -> str:
    if h_plain in _HAZARD_NOUNS:
        return _HAZARD_NOUNS[h_plain]
    if h_plain.endswith("belastung"):
        return h_plain
    return f"{h_plain}belastung"


def _narrative_pathway_title(h_name: str, e_name: str, v_name: str) -> str:
    h = _plain_name(h_name)
    e = _plain_name(e_name)
    v = _plain_name(v_name)
    h_noun = _hazard_noun(h)
    if e.startswith(("älter", "vulnerab", "dicht", "hohem", "Gefahren", "Gebäude")):
        prep_e = "der" if e.startswith(("älter", "vulnerab", "hohem")) else "in"
        if e.startswith("dicht"):
            return f"{h_noun} in {e}"
        if e.startswith("älter"):
            return f"{h_noun} der älteren Bevölkerung"
        return f"{h_noun} für {e}"
    if v.startswith(("eingeschränkt", "schwachem", "fehlender", "geringer", "erhöhter", "schlechter")):
        return f"{h_noun} für {e} mit {v}"
    if v in ("Hitzesensitivität",):
        return f"{h_noun} für {e} bei {v}"
    return f"{h_noun} für {e} mit {v}"


def _has_tech_prefix(text: str) -> bool:
    return any(text.startswith(p) for p in _TECH_PREFIXES)


def _plain_name(name: str) -> str:
    return _PLAIN_INDICATOR_NAMES.get(name, name)


def pathway_display_name(
    risk_code: str,
    pathway_type: str,
    hazard: str,
    exposure: str,
    vulnerability: str,
    h_name: str,
    e_name: str,
    v_name: str,
) -> str:
    """Klarer Anzeigename für eine Wirkungskette – ohne Fachjargon-Präfixe."""
    key = (risk_code, hazard, exposure, vulnerability)
    curated = PATHWAY_DESCRIPTIONS.get(key)
    if curated and not _has_tech_prefix(curated):
        return curated

    return _narrative_pathway_title(h_name, e_name, v_name)


def get_pathway_description(
    risk_code: str,
    hazard: str,
    exposure: str,
    vulnerability: str,
    pathway_type: str,
    h_name: str,
    e_name: str,
    v_name: str,
) -> str:
    return pathway_display_name(
        risk_code, pathway_type, hazard, exposure, vulnerability,
        h_name, e_name, v_name,
    )


def fallback_chain_title(type_label, h_name, e_name, v_name):
    h, e, v = _plain_name(h_name), _plain_name(e_name), _plain_name(v_name)
    return f"{h} – {e}, {v}"


def chain_label(h_name, e_name, v_name):
    return f"{h_name} × {e_name} × {v_name}"
